-- Second batch of explicitly labelled supplemental study outlines for MBH histology.
-- This is an idempotent data migration; it never overwrites an existing answer.
with supplemental_answers(id, answer) as (
  values
  ('75a81181-cb1f-59c8-a7c7-7966c03f8bff', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Метаплазия — обратимая замена одного дифференцированного типа клеток другим в ответ на хроническое раздражение или изменение микроокружения. Пример: замена реснитчатого эпителия бронхов многослойным плоским при длительном курении; кишечная метаплазия эпителия желудка при хроническом воспалении. Механизм связан с изменением программы дифференцировки стволовых/прогениторных клеток. Метаплазия может повышать устойчивость к раздражителю, но при сохраняющемся повреждении увеличивает риск дисплазии; это не то же самое, что непосредственное превращение зрелой клетки в другую.'),
  ('22d1fbc0-278b-5df7-ba5d-990446e293fc', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Покровный эпителий классифицируют по числу слоёв (однослойный, многослойный, многорядный) и форме поверхностных клеток (плоские, кубические, цилиндрические); выделяют также переходный эпителий. Он покрывает поверхность и полости, обеспечивает барьер, транспорт, секрецию и рецепцию. Питание происходит диффузией из подлежащей соединительной ткани через базальную мембрану. Регенерация обеспечивается камбиальными клетками: в однослойном кишечном эпителии — криптами, в эпидермисе — базальным слоем, в многослойном эпителии — преимущественно базальными клетками.'),
  ('bce83f16-6fec-563f-81d6-1e0051edc91f', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эпителии состоят из тесно прилегающих полярных клеток, лежат на базальной мембране, не содержат собственных сосудов и быстро обновляются. Базальная мембрана включает базальную пластинку (ламинины, коллаген IV и другие компоненты) и связанную ретикулярную пластинку; она поддерживает эпителий, фильтрует, участвует в регенерации и определяет полярность. Специализированные структуры: микроворсинки для всасывания, реснички для перемещения жидкости/частиц, стереоцилии для всасывания или механорецепции; межклеточные контакты обеспечивают сцепление и барьер.'),
  ('42fe4537-e52e-566c-bcf4-afdfc223e69c', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Реснитчатый эпителий содержит клетки с подвижными ресничками, которые перемещают слизь и частицы; бокаловидные клетки выделяют слизь. Однослойный многорядный реснитчатый эпителий выстилает большую часть дыхательных путей: все клетки контактируют с базальной мембраной, но не все достигают поверхности. Реснички имеют аксонему с микротрубочками по схеме 9+2 и двигаются за счёт динеиновых моторных белков. В препарате ищите ядра на разных уровнях, реснитчатую апикальную поверхность и бокаловидные клетки.'),
  ('0f2fdf21-6e9b-512e-98fd-3abc6dcb4bd3', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Поверхность кишечника выстлана однослойным цилиндрическим эпителием с энтероцитами и бокаловидными клетками; в тонкой кишке ворсинки увеличивают площадь всасывания, а микроворсинки энтероцитов образуют щёточную каёмку. Клетки Панета в основании крипт выделяют антимикробные вещества, энтероэндокринные клетки — гормоны. Обновление происходит из стволовых клеток крипт: потомки дифференцируются и мигрируют к вершине ворсинки, а затем слущиваются. Питание обеспечивается диффузией из сосудов собственной пластинки слизистой.'),
  ('e73e4542-9f4c-5f11-a5e8-a93d46f863c0', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Многослойный плоский ороговевающий эпителий образует эпидермис кожи. В базальном слое клетки пролиферируют; шиповатый слой содержит десмосомы, зернистый — кератогиалин, а в роговом слое находятся уплощённые безъядерные корнеоциты с кератином. Эпителий ограничивает потерю воды и защищает от механических, химических и микробных воздействий. Он аваскулярен и питается диффузией из дермы; обновление идёт за счёт базальных кератиноцитов.'),
  ('a42f0ac2-cb43-5c95-95b2-353618d53285', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Выделяют гладкую, поперечно-полосатую скелетную и поперечно-полосатую сердечную мышечные ткани. Скелетная ткань состоит из длинных многоядерных волокон с периферическими ядрами и выраженной исчерченностью; регенерация ограничена, частично обеспечивается сателлитными клетками. Сердечная ткань образована ветвящимися кардиомиоцитами с центральными ядрами и вставочными дисками; восстановление ограничено. Гладкая ткань состоит из одноядерных веретеновидных миоцитов без саркомеров и способна к более выраженной гипертрофии и пролиферации. Источники развития зависят от типа и локализации.'),
  ('a0f2f072-3518-58ac-85c5-d52c300ff991', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Нейрон состоит из тела, дендритов и аксона. По числу отростков различают мультиполярные, биполярные и псевдоуниполярные нейроны; по функции — чувствительные, вставочные и двигательные. Тело содержит ядро, ядрышко, гранулярную ЭПС и аппарат Гольджи; вещество Ниссля отсутствует в аксонном холмике и аксоне. Дендриты обычно принимают входные сигналы, аксон проводит потенциал действия к окончаниям. Нейроны контактируют через синапсы и часто имеют ограниченную способность к делению.'),
  ('a377e7af-b01d-539a-b92d-e34679b1168e', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Нервная ткань включает нейроны и нейроглию; нейроны принимают, интегрируют и передают сигналы, а глия обеспечивает поддержку, изоляцию, питание и защиту. Нейроны развиваются преимущественно из нейроэктодермы нервной трубки и нервного гребня; микроглия имеет мезодермальное/моноцитарное происхождение. Астроциты регулируют микроокружение, олигодендроциты формируют миелин в ЦНС, эпендимоциты выстилают полости, микроглия фагоцитирует; в ПНС важны шванновские и сателлитные клетки.'),
  ('dd5be38e-64b4-52ac-be51-76ce16f249f9', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Миелиновое нервное волокно включает аксон и сегментированную миелиновую оболочку; в ПНС сегменты формируют шванновские клетки, в ЦНС — олигодендроциты. Между сегментами находятся узлы Ранвье, благодаря которым возбуждение проводится скачкообразно и быстрее. Безмиелиновые волокна не имеют компактной многослойной миелиновой оболочки; в ПНС несколько тонких аксонов могут располагаться в углублениях одной шванновской клетки. Оба типа проводят импульсы, но скорость и энергетические свойства различаются.'),
  ('939ca7eb-c674-5388-b0b1-cbc6fbd97da0', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Рецепторы классифицируют по строению (свободные окончания, неинкапсулированные и инкапсулированные), по расположению (экстеро-, интеро- и проприорецепторы) и по виду стимула (механо-, термо-, хемо-, фото- и ноцицепторы). Инкапсулированные рецепторы имеют нервное окончание, окружённое специализированными клетками и/или соединительнотканной капсулой. Тельца Пачини воспринимают глубокое давление и вибрацию; тельца Мейснера связаны с тонким осязанием; мышечные веретёна воспринимают растяжение мышцы. Конкретная функция зависит от рецептора и его локализации.'),
  ('35d823bd-4027-5a81-a3d8-7706420f214f', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Эпидермис — многослойный плоский ороговевающий эпителий; основные клетки — кератиноциты. Различают базальный, шиповатый, зернистый и роговой слои; в толстой коже дополнительно выражен блестящий слой. Меланоциты образуют меланин, клетки Лангерганса участвуют в иммунной защите, клетки Меркеля связаны с осязанием. Эпидермис не содержит сосудов; питание диффузное из дермы. Регенерация обеспечивается пролиферацией базальных кератиноцитов и их последующей дифференцировкой.'),
  ('075986d2-7e24-572f-a685-ce577dd0899d', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Переходный эпителий (уротелий) выстилает почечные чашечки, лоханки, мочеточники и мочевой пузырь. Он многослойный: базальные клетки, промежуточные клетки и крупные поверхностные «зонтичные» клетки, часто двуядерные. При растяжении эпителий становится тоньше, а поверхностные клетки уплощаются; плотные контакты и специализированная апикальная мембрана ограничивают проникновение компонентов мочи. В препарате обращайте внимание на изменчивую толщину и куполообразные поверхностные клетки в ненаполненном органе.'),
  ('ea227080-ede9-52a7-b10d-751b626ab23c', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Однослойный многорядный реснитчатый эпителий характерен для проводящих дыхательных путей. Он включает реснитчатые, бокаловидные, базальные и другие специализированные клетки; все клетки опираются на базальную мембрану, но не все достигают просвета. Реснички продвигают слизь к глотке, обеспечивая мукоцилиарный клиренс; бокаловидные клетки увлажняют поверхность слизью. В препарате диагностичны ядра на разной высоте, реснички и бокаловидные клетки.'),
  ('45bdeb86-161f-5687-b6a2-175b865f32aa', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Морфологически нейроны бывают мультиполярными (много дендритов и один аксон), биполярными (один дендрит и один аксон) и псевдоуниполярными (единый отросток делится на периферическую и центральную ветви). Функционально выделяют чувствительные, вставочные и двигательные нейроны. Тело нейрона содержит ядро и органеллы синтеза белка; дендриты принимают сигналы, аксон проводит возбуждение от перикариона. Для описания препарата укажите форму тела, ядро, вещество Ниссля и направление отростков, если оно различимо.'),
  ('e9589708-58c3-503c-b5ae-b56fc91d04d3', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Многослойный плоский неороговевающий эпителий покрывает влажные поверхности, подверженные трению, например полость рта, пищевод и влагалище. Базальные клетки делятся, промежуточные созревают, поверхностные остаются живыми и сохраняют ядра; роговой слой отсутствует. Эпителий защищает от механического повреждения и сохраняет влажную поверхность. Сосудов в нём нет: питание идёт диффузией из соединительной ткани через базальную мембрану. Регенерация обеспечивается клетками базального слоя.'),
  ('c8f2795b-2a42-5c6b-b58a-7132473a04f9', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Межнейронный синапс — специализированный контакт между нейронами. В химическом синапсе потенциал действия вызывает вход Ca2+ в пресинаптическое окончание, экзоцитоз везикул с медиатором и связывание медиатора с постсинаптическими рецепторами; передача обычно односторонняя. В электрических синапсах ток проходит через щелевые контакты и передача очень быстрая. По месту контакта различают аксо-дендритические, аксо-соматические и аксо-аксональные синапсы; по эффекту — возбуждающие и тормозные.'),
  ('9dda6792-c2c4-5bbd-a5bb-033ca58bd2d4', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). В ЦНС астроциты поддерживают ионный и метаболический гомеостаз, олигодендроциты формируют миелин, микроглия обеспечивает иммунный надзор и фагоцитоз, эпендимоциты выстилают желудочки мозга и центральный канал. В ПНС шванновские клетки миелинизируют аксоны или окружают безмиелиновые волокна; клетки-сателлиты окружают тела нейронов в ганглиях. Большинство глиоцитов не проводит нервные импульсы так, как нейроны, но поддерживает их работу и среду нервной ткани.'),
  ('1e423ec8-2f95-5ec8-a1fe-b8b6eb6b1f47', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Миелиновые волокна имеют толстую многослойную оболочку и узлы Ранвье; в ПНС каждый миелиновый сегмент образован одной шванновской клеткой, в ЦНС — отростком олигодендроцита. Безмиелиновые периферические аксоны обычно лежат в цитоплазматических желобках шванновских клеток без компактного миелина. Миелиновые волокна обеспечивают быстрое скачкообразное проведение, безмиелиновые — более медленное непрерывное. В препарате ищите осевой цилиндр, оболочку и узловые перехваты, если они попали в срез.'),
  ('ae816238-55a2-5a55-8027-05833f30b73d', 'Учебный конспект MEDBIOHIM (дополнение; сверьте с лекцией). Нервные окончания делят на чувствительные (рецепторные) и эффекторные (двигательные, секреторные); по строению рецепторы бывают свободными и инкапсулированными. По стимулу различают механорецепторы, терморецепторы, хеморецепторы, фоторецепторы и ноцицепторы. Свободные окончания воспринимают, в частности, боль и температуру; инкапсулированные структуры, например тельца Пачини, реагируют на механические воздействия. Эффекторные окончания передают сигнал мышечным клеткам или железам.')
)
update public.exam_questions q
set answer = s.answer, updated_at = now()
from supplemental_answers s
where q.id = s.id::uuid
  and q.subject_slug = 'histology'
  and nullif(btrim(q.answer), '') is null;
